52	    ///
53	    /// Returns `None` if this is a [`Linebreak`](RawMathItem::Linebreak) or
54	    /// [`Align`](RawMathItem::Align).
55	    pub(crate) fn into_item(self) -> Option<MathItem<'a>> {
56	        match self {
57	            Self::Item(item) => Some(item),
58	            Self::Linebreak | Self::Align => None,
59	        }
