965	            text,
966	            class: class.unwrap_or(MathClass::Normal),
967	            stretch: Cell::new(Stretch::new()),
968	            mid_stretched: Cell::new(None),
969	            flac: Cell::new(false),
970	        }));
971	        let props = MathProperties::new(styles, class, span).with_limits(limits);
972	        MathComponent { kind, props, styles }.into()
