1187	        if let Some(info) = self.0.get_mut(axis)
1188	            && let Some(buffer) = info.buffer
1189	        {
1190	            // Sort out the buffer before returning the info to use.
1191	            if info.relative_to.is_some() {
1192	                info.target = buffer;
1193	            } else {
1194	                info.target = Rel::new(
1195	                    info.target.rel * buffer.rel,
1196	                    buffer.rel.of(info.target.abs) + buffer.abs,
1197	                );
