241	    ctx: &mut MathResolver<'a, '_, '_>,
242	    styles: StyleChain<'a>,
243	) -> SourceResult<()> {
244	    let body = if styles.get(TargetElem::target).is_html() {
245	        body.map(|body| ctx.resolve_into_item(body, styles)).transpose()?
246	    } else {
247	        None
248	    };
