253	/// Resolves horizontal spacing.
254	fn resolve_h(
255	    elem: &Packed<HElem>,
256	    ctx: &mut MathResolver,
257	    styles: StyleChain,
258	) -> SourceResult<()> {
259	    if let Spacing::Rel(rel) = elem.amount
260	        && rel.rel.is_zero()
261	    {
262	        ctx.push(MathItem::Spacing(
263	            rel.abs,
264	            styles.resolve(TextElem::size),
265	            elem.weak.get(styles),
266	        ));
267	    }
268	    Ok(())
269	}
