271	/// Resolves text content.
272	fn resolve_text<'a>(
273	    elem: &Packed<TextElem>,
274	    ctx: &mut MathResolver<'a, '_, '_>,
275	    styles: StyleChain<'a>,
276	) -> SourceResult<()> {
277	    let variant = styles.get(EquationElem::variant);
278	    let bold = styles.get(EquationElem::bold);
279	    // Disable auto-italic.
280	    let italic = styles.get(EquationElem::italic).or(Some(false));
281	
282	    // Create item with correct styles and properties.
283	    let local_styles = ctx.store_chain(styles).chain(&*TEXT_BASE_LOCAL_STYLES);
284	    let mut create_item = |text: &str| {
285	        let mut decimal_count = 0;
286	        let num = text.chars().all(|c| {
287	            if c == '.' {
288	                decimal_count += 1;
289	            }
290	            c.is_ascii_digit() || c == '.'
291	        }) && decimal_count != text.len() // at least one digit
292	            && decimal_count <= 1; // at most one dot
293	        let styled_text: EcoString = text
294	            .chars()
295	            .flat_map(|c| to_style(c, MathStyle::select(c, variant, bold, italic)))
296	            .collect();
297	        if num {
298	            NumberItem::create(styled_text, styles, elem.span())
299	        } else {
300	            TextItem::create(
301	                styled_text,
302	                local_styles,
303	                elem.span(),
304	                ctx.locator.next(&elem.span()),
305	            )
306	        }
307	    };
308	
309	    // Strip a single trailing newline.
310	    let mut lines = split_newlines(&elem.text);
311	    lines.pop_if(|x| x.is_empty());
312	
313	    let item = if let [text] = lines.as_slice() {
314	        create_item(text)
315	    } else {
316	        let rows = lines
317	            .into_iter()
318	            .map(|line| AlignedRow::new(vec![create_item(line)]))
319	            .collect();
320	        MultilineItem::create(rows, styles).with_multiline_centering()

