417	/// This is a mutable stack-allocated linked list used for attachment merging.
418	///
419	/// Consider: `attach(attach(attach(a, t: 1), b: 2), t: 3, b: 4)`.
420	/// We would like this to become `attach(attach(a, t: 1, b: 2), t: 3, b: 4)`.
421	///
422	/// However if we only consider attachments in adjacent levels, we won't merge
423	/// `b:4` inward because `b:2` is already present (but we will merge `t:3` in).
424	/// But at the next step `b:2` would merge inwards, leaving us with the sorry
425	/// state of `attach(attach(attach(a, t: 1, b: 2), t: 3), b: 4)` with `t:3` and
426	/// `b:4` separated, despite originally starting at the same level!
427	///
428	/// So for correct handling we need a proper list of attachments, for which I am
429	/// using a stack-allocated linked list to avoid allocations and because it's
430	/// relatively straightforward.
431	///
432	/// Unfortunately, this does require the complication of interior mutability,
433	/// i.e. the `Cell` type, due to lifetime variance. See the linked section of
434	/// "Learning Rust With Entirely Too Many Linked Lists" for more explanation:
435	/// <https://rust-unofficial.github.io/too-many-lists/infinity-stack-allocated.html>
436	enum AttachmentList<'a> {
437	    Node {
438	        /// We use `Option<Content>` instead of just `Content` to allow for the
439	        /// "unmerging" operation used by primes in tr position.
440	        data: Cell<Option<Content>>,
441	        outer: &'a AttachmentList<'a>,
442	    },
443	    End,
444	}
445	
446	impl<'a> AttachmentList<'a> {
447	    fn inner(content: Option<Content>, outer: &'a Self) -> Self {
448	        fn merge_inward(list: &AttachmentList) -> Option<Content> {
449	            match list {
450	                AttachmentList::Node { data, outer } => data.replace(merge_inward(outer)),
451	                AttachmentList::End => None,
452	            }
453	        }
454	        let data = content.or_else(|| merge_inward(outer));
455	        AttachmentList::Node { data: Cell::new(data), outer }
456	    }
457	
458	    fn unmerge(mut self: &Self, content: Content) {
459	        let mut data = Some(content);
460	        while data.is_some()
461	            && let AttachmentList::Node { data: outer_data, outer } = self
462	        {
463	            data = outer_data.replace(data);
464	            self = outer;
465	        }
466	        assert!(data.is_none(), "only called if we previously merged inward");
467	    }
468	}
