470	/// Recursively resolve the base of an `AttachElem`, merging outer attachments
471	/// inwards.
472	fn resolve_inner_attach<'a>(
473	    elem: &'a Packed<AttachElem>,
474	    outer_attachments: &[AttachmentList; 6],
475	    outer_t_inside_tr: bool,
476	    ctx: &mut MathResolver<'a, '_, '_>,
477	    styles: StyleChain<'a>,
478	) -> SourceResult<MathItem<'a>> {
479	    // Lifetime-extend the super/subscript styles.
480	    let bumped_styles = ctx.store_chain(styles);
481	    let sup_style = ctx.store_styles(style_for_superscript(styles));
482	    let sup_style_chain = bumped_styles.chain(sup_style);
483	    let sub_style = ctx.store_styles(style_for_subscript(styles));
484	    let sub_style_chain = bumped_styles.chain(sub_style);
485	
486	    // Get the merged attachments without resolving them to items yet.
487	    let (no_inner_tr, t_inside_tr);
488	    let attachments = {
489	        let [o_t, o_b, o_tl, o_tr, o_bl, o_br] = outer_attachments;
490	
491	        let tl = AttachmentList::inner(elem.tl.get_cloned(sup_style_chain), o_tl);
492	        // We remember the status of t and tr for correct prime handling below.
493	        let elem_t = elem.t.get_cloned(sup_style_chain);
494	        let elem_tr = elem.tr.get_cloned(sup_style_chain);
495	        no_inner_tr = elem_tr.is_none();
496	        t_inside_tr = no_inner_tr && (elem_t.is_some() || outer_t_inside_tr);
497	        let t = AttachmentList::inner(elem_t, o_t);
498	        let tr = AttachmentList::inner(elem_tr, o_tr);
499	
500	        let b = AttachmentList::inner(elem.b.get_cloned(sub_style_chain), o_b);
501	        let bl = AttachmentList::inner(elem.bl.get_cloned(sub_style_chain), o_bl);
502	        let br = AttachmentList::inner(elem.br.get_cloned(sub_style_chain), o_br);
503	
504	        [t, b, tl, tr, bl, br]
505	    };
506	
507	    // Extract from a nested EquationElem.
508	    let mut base_elem = &elem.base;
509	    while let Some(equation) = base_elem.to_packed::<EquationElem>() {
510	        base_elem = &equation.body;
511	    }
512	
513	    // Resolve the base and recursively merge outer attachments inwards.
514	    let base = if let Some(base_elem) = base_elem.to_packed::<AttachElem>() {
515	        resolve_inner_attach(base_elem, &attachments, t_inside_tr, ctx, styles)?
516	    } else {
517	        ctx.resolve_into_item(base_elem, styles)?
518	    };
519	
520	    // We can now take our inner attachments back out of the list.
521	    let [t, b, tl, tr, bl, br] = attachments.map(|a| match a {
522	        AttachmentList::Node { data: content, outer: _ } => content.into_inner(),
523	        AttachmentList::End => None,
524	    });
525	
526	    // If we're not actually attaching anything, just return the base.
527	    if [&t, &b, &tl, &tr, &bl, &br].iter().all(|a| a.is_none()) {
528	        return Ok(base);
529	    }
530	
531	    // Apply limits, potentially joining top-right primes with the top attachment.
532	    let limits = base.limits().active(styles);
533	    let (t, tr) = match (t, tr) {
534	        (Some(t), Some(tr)) if !limits => {
535	            let primed = tr.is::<PrimesElem>();
536	            if primed && no_inner_tr && t_inside_tr {
537	                // If we brought a primed tr inward, yield it back to the outer
538	                // attachment to avoid inverting the order with `tr + t`.
539	                // And note that `t + tr` would just look bad.
540	                outer_attachments[3].unmerge(tr);
541	                (None, Some(t))
542	            } else if primed {
543	                // This makes `x'^2` look better than `x^'^2`.
544	                (None, Some(tr + t))
545	            } else {
546	                (Some(t), Some(tr))
547	            }
548	        }
549	        (Some(t), None) if !limits => (None, Some(t)),
550	        (t, tr) => (t, tr),
551	    };
552	    let (b, br) = if limits || br.is_some() { (b, br) } else { (None, b) };
553	
554	    // Finally, resolve the attachments themselves from content to items.
555	    macro_rules! layout {
556	        ($content:ident, $style_chain:ident) => {
557	            $content
558	                .map(|elem| ctx.resolve_into_item(ctx.store(elem), $style_chain))
559	                .transpose()
560	        };
561	    }
562	
563	    let top = layout!(t, sup_style_chain)?;
564	    let bottom = layout!(b, sub_style_chain)?;
565	    let top_left = layout!(tl, sup_style_chain)?;
566	    let bottom_left = layout!(bl, sub_style_chain)?;
567	    let top_right = layout!(tr, sup_style_chain)?;
568	    let bottom_right = layout!(br, sub_style_chain)?;
569	
570	    Ok(ScriptsItem::create(
571	        base,
572	        top,
573	        bottom,
574	        top_left,
575	        bottom_left,
576	        top_right,
577	        bottom_right,
578	        styles,
579	    ))
580	}
