851	/// Resolves a left/right element.
852	fn resolve_lr<'a>(
853	    elem: &'a Packed<LrElem>,
854	    ctx: &mut MathResolver<'a, '_, '_>,
855	    styles: StyleChain<'a>,
856	) -> SourceResult<()> {
857	    // Extract from an EquationElem.
858	    let mut body = &elem.body;
859	    if let Some(equation) = body.to_packed::<EquationElem>() {
860	        body = &equation.body;
861	    }
862	
863	    // Extract implicit LrElem.
864	    if let Some(lr) = body.to_packed::<LrElem>()
865	        && lr.size.get(styles).is_one()
866	    {
867	        body = &lr.body;
868	    }
869	
870	    let start = ctx.resolve_into_items(body, styles)?;
871	
872	    // Ignore leading and trailing ignorant items.
873	    let (start_idx, end_idx) =
874	        ctx.items[start..].split_prefix_suffix(|f| f.is_ignorant());
875	    let inner_range = (start + start_idx)..(start + end_idx);
876	    let inner_items = &mut ctx.items[inner_range.clone()];
877	
878	    let size = elem.size.get(styles);
879	    let font_size = styles.resolve(TextElem::size);
880	    let stretch =
881	        Stretch::new().with_y(StretchInfo::from_size(size, DELIM_SHORT_FALL, font_size));
882	
883	    let scale_if_delimiter = |item: &mut MathItem, apply: Option<MathClass>| {
884	        if matches!(
885	            item.class(),
886	            MathClass::Opening | MathClass::Closing | MathClass::Fence
887	        ) {
888	            item.set_stretch(stretch);
889	            if let Some(class) = apply {
890	                item.set_class(class);
891	            }
892	        }
893	    };
894	
895	    // Scale up items at both ends.
896	    match inner_items {
897	        [one] => {
898	            if let RawMathItem::Item(one) = one {
899	                if let MathItem::Component(MathComponent {
900	                    kind: MathKind::Fenced(fenced),
901	                    ..
902	                }) = one
903	                {
904	                    if let Some(open) = &fenced.open {
905	                        open.set_stretch(stretch);
906	                    }
907	                    if let Some(close) = &fenced.close {
908	                        close.set_stretch(stretch);
909	                    }
910	                    for item in fenced.body.as_slice() {
911	                        if item.mid_stretched() == Some(true) {
912	                            item.set_stretch(stretch);
913	                        }
914	                    }
915	                } else {
916	                    let mut info =
917	                        StretchInfo::new(size.abs.at(font_size).into(), DELIM_SHORT_FALL);
918	                    if !size.is_one() {
919	                        info.requested_target = Some(size);
920	                    }
921	                    one.set_y_stretch(info);
922	                }
923	            }
924	            return Ok(());
925	        }
926	        [first, .., last] => {
927	            if let RawMathItem::Item(first) = first {
928	                scale_if_delimiter(first, Some(MathClass::Opening));
929	            }
930	            if let RawMathItem::Item(last) = last {
931	                scale_if_delimiter(last, Some(MathClass::Closing));
932	            }
933	        }
934	        [] => {}
935	    }
936	
937	    // Handle MathItem::Glyph items that should be scaled up.
938	    for item in inner_items.iter_mut() {
939	        if let RawMathItem::Item(item) = item
940	            && item.mid_stretched() == Some(false)
941	        {
942	            item.set_mid_stretched(Some(true));
943	            item.set_stretch(stretch);
944	        }
945	    }
946	
947	    let mut inner_items: Vec<_> = ctx.items.drain(inner_range).collect();
948	
949	    // Remove weak Spacing immediately after the opening or immediately
950	    // before the closing.
951	    let mut index = 0;
952	    let len = inner_items.len();
953	    let opening_exists = inner_items.first().is_some_and(
954	        |f| matches!(f, RawMathItem::Item(item) if item.class() == MathClass::Opening),
955	    );
956	    let closing_exists = inner_items.last().is_some_and(
957	        |f| matches!(f, RawMathItem::Item(item) if item.class() == MathClass::Closing),
958	    );
959	    inner_items.retain(|item| {
960	        let discard = (index == 1 && opening_exists
961	            || index + 2 == len && closing_exists)
962	            && matches!(item, RawMathItem::Item(MathItem::Spacing(_, _, true)));
963	        index += 1;
964	        !discard
965	    });
966	
967	    let open = opening_exists.then(|| inner_items.remove(0).into_item().unwrap());
968	    let close = closing_exists.then(|| inner_items.pop().unwrap().into_item().unwrap());
969	
970	    let insert_pos = start + start_idx;
971	    match process_group(inner_items, styles, close.is_some(), false, true) {
972	        GroupResult::Multiline(rows) => {
973	            let items = expand_multiline_fence(rows, open, close, styles, elem.span());
974	            ctx.items.splice(insert_pos..insert_pos, items);
975	        }
976	        GroupResult::Flat(items) => {
977	            let body = GroupItem::create(items, styles);
978	            let item = FencedItem::create(open, close, body, true, styles, elem.span());
979	            ctx.items.insert(insert_pos, item.into());
980	        }
981	    }
982	
983	    Ok(())
984	}
